import argparse,pathlib,json,hashlib,sys
from fractions import Fraction as F
P=pathlib.Path(__file__).resolve().parent;H=lambda b:hashlib.sha256(b).hexdigest()
def check(sp,fp,out):
 s=json.loads(sp.read_text());f=json.loads(fp.read_text());contract=json.loads((P/'CONTRACT.json').read_text());a,b,c,d,e=[F(s['coefficients'][x]) for x in 'ABCDE'];x=F(f['temperature_start'])/1000;y=F(f['temperature_end'])/1000;n=F(f['amount_mol']);dt=y-x
 cp0=a+b*x+c*x*x+d*x*x*x+e/(x*x);cp1=a+b*y+c*y*y+d*y*y*y+e/(y*y)
 # Independent factorized integral: differences of powers factored, inverse term exact.
 q=n*1000*dt*(a+b*(x+y)/2+c*(x*x+x*y+y*y)/3+d*(x**3+x*x*y+x*y*y+y**3)/4+e/(x*y));fixed=n*F('75.38')*(F(f['temperature_end'])-F(f['temperature_start']));cp=json.loads((out/'04_cp.json').read_text());v=json.loads((out/'05_integral.json').read_text());v2=json.loads((out/'06_comparison.json').read_text());math=F(cp['cp_start_J_per_mol_K'])==cp0 and F(cp['cp_end_J_per_mol_K'])==cp1 and F(v['heat_J'])==q and F(v2['constant_heat_J'])==fixed and F(v2['difference_integrated_minus_constant_J'])==q-fixed; ex=json.loads((P/'expected_sha256.json').read_text());obs={k:H((out/k).read_bytes()) for k in ex};commit=json.loads((out/'07_commitment.json').read_text());consistent=commit['artifacts']=={k:H((out/k).read_bytes()) for k in ex if k!='07_commitment.json'};bound=H(sp.read_bytes())==contract['source_record_sha256'] and H(fp.read_bytes())==contract['fixture_sha256'] and H((P/'source_extract.txt').read_bytes())==contract['extract_sha256'] and H((P/'expected_sha256.json').read_bytes())==contract['expected_sha256_file_sha256'];return {'status':'PASS' if math and obs==ex and consistent and bound else 'REJECT','math':math,'hashes':obs==ex,'commitment_consistent':consistent,'frozen_bindings':bound}
if __name__=='__main__':
 x=argparse.ArgumentParser();x.add_argument('--source',type=pathlib.Path,default=P/'source_record.json');x.add_argument('--fixture',type=pathlib.Path,default=P/'fixture.json');x.add_argument('--out',type=pathlib.Path,required=True);z=x.parse_args();r=check(z.source,z.fixture,z.out);print(json.dumps(r,sort_keys=True));sys.exit(0 if r['status']=='PASS' else 1)
